182      public static Applicable checkAndLoadNative(Applicable defn, boolean isFunctionalMethod,
183                                                  com.sun.fortress.interpreter.evaluator.types.FType declarer) {
184          Option<Expr> optBody = NodeUtil.getBody(defn);
185          if (optBody.isNone()) return defn;
186          Expr body = optBody.unwrap();
187          Expr fn;
188          Expr arg;
189          if (body instanceof Juxt && ((Juxt) body).isTight()) {
190              List<Expr> juxts = ((Juxt) body).getExprs();
191              if (juxts.size() != 2) return defn;
192              fn = juxts.get(0);
193              arg = juxts.get(1);
194          } else if (body instanceof MathPrimary) {
195              MathPrimary mp = (MathPrimary) body;
196              List<MathItem> args = mp.getRest();
197              if (args.size() != 1) return defn;
198              fn = mp.getFront();
199              MathItem mi = args.get(0);
200              if (mi instanceof ExprMI) arg = ((ExprMI) mi).getExpr();
201              else return defn;
202          } else // (!(body instanceof TightJuxt || body instanceof MathPrimary))
203              return defn;
204          if (!(fn instanceof VarRef)) return defn;
205          if (!(arg instanceof StringLiteralExpr)) return defn;
206          Id name = ((VarRef) fn).getVarId();
207          if (!name.getText().equals("builtinPrimitive")) return defn;
208          String str = ((StringLiteralExpr) arg).getText();
209          String own = OWN_OPERATIONS.get(str);
210          if (own != null) str = own;
211          Pair<String, Applicable> key = new Pair<String, Applicable>(str, defn);
212          synchronized (cache) {
213              NativeApp res = cache.get(key);
214              if (res != null) return res;
215              if (StaticNativeApp.isHelperString(str)) {
216                  Object found = StaticNativeApp.find(str, defn, declarer);
217                  if (found instanceof String) return bug(defn, (String) found);
218                  res = new StaticNativeApp((java.lang.reflect.Method) found, defn);
219                  res.init(defn, isFunctionalMethod);
220                  cache.put(key, res);
221                  return res;
222              }
223              try {
224                  // System.err.println("Loading primitive class "+str);
225                  Class nativeAct = Class.forName(str);
226                  res = (NativeApp) nativeAct.newInstance();
227                  res.init(defn, isFunctionalMethod);
228                  cache.put(key, res);
229                  return res;
230              }
231              catch (java.lang.ClassNotFoundException x) {
232                  return bug(defn, "Native class " + str + " not found.", x);
233              }
234              catch (java.lang.InstantiationException x) {
235                  return bug(defn, "Native class " + str + " has no nullary constructor.", x);
236              }
237              catch (java.lang.IllegalAccessException x) {
238                  return bug(defn, "Native class " + str + " cannot be accessed.", x);
239              }
240              catch (java.lang.ClassCastException x) {
241                  return bug(defn, "Native class " + str + " is not a NativeApp.", x);
