    public void set(int i, T value) {
        array[i].assignValue((FValue) value);
    }

    /**
     * Init is equivalent to set, but fails (returns false) for non-null
     * contents.
     */
    public boolean init(int i, T value) {
        if (get(i) == null) {
            array[i].storeValue((FValue) value);
            return true;
        } else return false;
    }

