import re, subprocess, sys
def strip(s):
    out=[];depth=0;i=0
    while i<len(s):
        if s.startswith('(*',i): depth+=1; i+=2; continue
        if depth and s.startswith('*)',i): depth-=1; i+=2; continue
        if not depth: out.append(s[i])
        i+=1
    return ''.join(out)
def files(rev):
    names=subprocess.check_output(['git','ls-tree','-r','--name-only',rev,'--','Library','ProjectFortress/LibraryBuiltin']).decode().split()
    return [n for n in names if n.endswith('.fss') and '/Compiler' not in n and '/incomplete/' not in n]
for rev in sys.argv[1:]:
    h=g=0
    for f in files(rev):
        s=strip(subprocess.check_output(['git','show',rev+':'+f]).decode('utf-8','replace'))
        for m in re.finditer(r'builtinPrimitive\s*\(\s*"([^"]*)"',s):
            if m.group(1).startswith('com.sun.fortress.nativeHelpers.'): h+=1
            else: g+=1
    print(rev, 'helper', h, 'glue', g, 'total', h+g)
EOF
